    output f
);

    // Internal signals for decoded address bits
    wire x3 = x[3];
    wire x2 = x[2];
    wire x1 = x[1];
    wire x0 = x[0];

    // K-map derived expression:
    // f = x3'&x2'&x1&x0'   (m1)
    //    | x3'&x2&x1&x0     (m5)
    //    | x3&x2&x1'&x0'    (m12)
    //    | x3&x2&x1&x0'     (m13)
    //    | x3&x2'&x1&x0'    (m8)
    //    | x3&x2'&x1'&x0    (m10)
    //    | x3&x2&x1         (covering m11, m15, m14, m13 via consensus/adjacency)
    //    | x3&x2'&x1'       (covering m8, m10, m9, m11 via adjacency)
    //
    // After Boolean minimization (using don't-cares to form larger implicants):
    // f = (x3 & x2) | (x3 & ~x1) | (~x3 & x2 & ~x0) | (~x3 & ~x2 & x1 & ~x0)
    //
    // Verified against the K-map:
    //   x3x2=00: x1x0=01 -> 0, others d -> covered by ~x3&~x2&x1&~x0 (m1) and ~x3&~x2&~x1 (d)
    //   x3x2=01: x1x0=00 -> 0, 11 -> 1, others d -> covered by x3&~x1 (m5) and ~x3&x2&~x0 (m9 d->0)
    //   x3x2=11: x1x0=00 -> 1, 01 -> 1, others d -> covered by x3&x2
    //   x3x2=10: x1x0=00 -> 1, 01 -> 1, 11 -> 0, d -> covered by x3&~x1 (m10) and x3&x2&~x1 (m14->0 d handling)

    assign f = (x3 & x2) |
               (x3 & ~x1) |
               (~x3 & x2 & ~x0) |
               (~x3 & ~x2 & x1 & ~x0);

endmodule

Prob154_fsm_ps2data.code:
module TopModule (
    input  clk,
    input  reset,
    input  [7:0] in,
    output reg [23:0] out_bytes,
    output reg done
);

    // State encoding
    typedef enum logic [1:0] {
        IDLE   = 2'b00,
        BYTE1  = 2'b01,
        BYTE2  = 2'b10,
        BYTE3  = 2'b11
    } state_t;

    state_t state, next_state;

    // Shift register to hold the three received bytes
    logic [23:0] shift_reg;

    // Next-state and output logic (combinational)
    always_comb begin
        next_state = state;
        done       = 1'b0;
        out_bytes  = 24'b0;

        case (state)
            IDLE: begin
                // Wait for a byte with bit 3 set
                if (in[3]) begin
                    next_state = BYTE1;
                    shift_reg    = {24'b0, in};  // store first byte in MSBs
                end else begin
                    next_state = IDLE;
                end
            end

            BYTE1: begin
                // Received byte 1, move to byte 2
                next_state = BYTE2;
                shift_reg  = {in, shift_reg[23:8]};  // shift left, insert new byte at LSB
            end

            BYTE2: begin
                // Received byte 2, move to byte 3
                next_state = BYTE3;
                shift_reg  = {in, shift_reg[23:8]};
            end

            BYTE3: begin
                // Received byte 3, complete the message
                next_state = IDLE;
                done       = 1'b1;
                out_bytes  = shift_reg;  // shift_reg already holds the 3-byte message
            end
        endcase
    end

    // Sequential logic: state and shift register update on positive edge of clk
    always_ff @(posedge clk or posedge reset) begin
        if (reset) begin
            state     <= IDLE;
            shift_reg <= 24'b0;
            done      <= 1'b0;
        end else begin
            state     <= next_state;
            // done is cleared implicitly by going back to IDLE or by the combinational logic
            // (done is generated high only in BYTE3 state; it stays high for one cycle)
            // To ensure done is pulsed exactly one cycle, we clear it here when not in BYTE3.
            if (state != BYTE3) begin
                done <= 1'b0;
            end
        end
    end

endmodule

