module TopModule (
    input  clk,
    input  resetn,
    input  x,
    input  y,
    output f,
    output g
);

    // State encoding: 2'b00 = A, 2'b01 = B, 2'b10 = C, 2'b11 = D
    reg [1:0] state, next_state;

    // State register (synchronous reset, active low)
    always @(posedge clk) begin
        if (!resetn)
            state <= 2'b00;  // State A
        else
            state <= next_state;
    end

    // Next-state logic
    always @(*) begin
        case (state)
            2'b00: begin // State A
                // After reset de-assertion, set f=1 for one cycle, go to B
                next_state = 2'b01;
            end
            2'b01: begin // State B
                // Monitor x for pattern 1,0,1
                if (x)
                    next_state = 2'b10; // x=1 -> C
                else
                    next_state = 2'b01; // x=0 -> stay B
            end
            2'b10: begin // State C
                // Monitor x=0 to complete pattern
                if (!x)
                    next_state = 2'b11; // x=0 -> D
                else
                    next_state = 2'b10; // x=1 -> stay C
            end
            2'b11: begin // State D
                // g=1 asserted, monitor y within 2 cycles
                if (y)
                    next_state = 2'b11; // y=1 -> stay D (g stays 1)
                else
                    next_state = 2'b00; // y=0 -> go to A (g will become 0)
            end
            default: next_state = 2'b00;
        endcase
    end

    // Output logic
    // f: set to 1 for one clock cycle after reset de-assertion (from A to B transition)
    assign f = (state == 2'b00) ? 1'b1 : 1'b0;

    // g: set to 1 when in state D, cleared when returning to A
    assign g = (state == 2'b11) ? 1'b1 : 1'b0;

endmodule

