module TopModule (
    input  clk,
    input  reset,
    output ena   [2:0],
    output q     [15:0]
);

    // Internal register to hold the 4-digit BCD counter value
    reg [15:0] counter;

    // Synchronous reset and count logic
    always @(posedge clk) begin
        if (reset) begin
            counter <= 16'd0;
        end else begin
            // BCD increment: if ones reach 9, roll over to 0 and carry to tens
            if (counter[3:0] == 4'd9) begin
                if (counter[7:4] == 4'd9) begin
                    if (counter[11:8] == 4'd9) begin
                        if (counter[15:12] == 4'd9) begin
                            // All digits at 9, roll over to 0
                            counter <= 16'd0;
                        end else begin
                            // Increment thousands digit
                            counter <= counter + 16'd1;
                        end
                    end else begin
                        // Increment hundreds digit and reset lower digits to 0
                        counter <= {counter[15:12] + 1'b1, 4'd0, counter[7:4], counter[3:0]};
                    end
                end else begin
                    // Increment tens digit and reset ones to 0
                    counter <= {counter[15:8], counter[7:4] + 1'b1, 4'd0};
                end
            end else begin
                // Simply increment the ones digit
                counter <= counter + 16'd1;
            end
        end
    end

    // ena outputs: enable signal for each upper digit increment
    // ena[0] enables tens digit increment (ones at 9)
    // ena[1] enables hundreds digit increment (tens and ones at 9)
    // ena[2] enables thousands digit increment (hundreds, tens, ones at 9)
    assign ena[0] = (counter[3:0] == 4'd9);
    assign ena[1] = (counter[7:4] == 4'd9) & (counter[3:0] == 4'd9);
    assign ena[2] = (counter[11:8] == 4'd9) & (counter[7:4] == 4'd9) & (counter[3:0] == 4'd9);

    // Continuous assignment to drive the output port q
    assign q = counter;

endmodule

