    end else begin
        state <= next_state;
        fall_counter <= next_fall_counter;
        walk_dir <= next_walk_dir;
        dig_dir <= next_dig_dir;
    end
end

// Next-state and counter logic
always_comb begin
    // Default values
    next_state = state;
    next_fall_counter = fall_counter;
    next_walk_dir = walk_dir;
    next_dig_dir = dig_dir;

    case (state)
        WALK_LEFT: begin
            if (!ground) begin
                // Start falling, remember direction
                next_state = FALLING;
                next_fall_counter = 1;
                next_walk_dir = $unsigned(WALK_LEFT); // Cast enum to logic
            end else if (dig) begin
                next_state = DIGGING;
                next_fall_counter = 0;
                next_dig_dir = $unsigned(WALK_LEFT); // Store direction before digging
            end else if (bump_left || bump_right) begin
                // Switch direction
                if (bump_left && !bump_right)
                    next_state = WALK_RIGHT;
                else if (bump_right && !bump_left)
                    next_state = WALK_LEFT;
                else // bumped on both sides
                    next_state = (state == WALK_LEFT) ? WALK_RIGHT : WALK_LEFT;
                next_walk_dir = $unsigned(next_state == WALK_RIGHT); // Update direction
                next_fall_counter = 0;
            end
        end

        WALK_RIGHT: begin
            if (!ground) begin
                next_state = FALLING;
                next_fall_counter = 1;
                next_walk_dir = $unsigned(WALK_RIGHT); // Cast enum to logic
            end else if (dig) begin
                next_state = DIGGING;
                next_fall_counter = 0;
                next_dig_dir = $unsigned(WALK_RIGHT); // Store direction before digging
            end else if (bump_left || bump_right) begin
                if (bump_left && !bump_right)
                    next_state = WALK_LEFT;
                else if (bump_right && !bump_left)
                    next_state = WALK_RIGHT;
                else
                    next_state = (state == WALK_LEFT) ? WALK_RIGHT : WALK_LEFT;
                next_walk_dir = $unsigned(next_state == WALK_RIGHT);
                next_fall_counter = 0;
            end
        end

        FALLING: begin
            if (ground) begin
                // Ground reappeared
                if (fall_counter >= 20) begin
                    // Fell for more than 20 cycles -> splatter
                    next_state = SPLATTERED;
                    next_fall_counter = 0;
                    next_walk_dir = walk_dir; // Don't care, but save
                end else begin
                    // Resume walking in same direction as before fall
                    if (walk_dir == 0) begin
                        next_state = WALK_LEFT;
                    end else begin
                        next_state = WALK_RIGHT;
                    end
                    next_fall_counter = 0;
                end
            end else begin
                // Ground still absent - increment counter
                next_fall_counter = fall_counter + 1;
                next_state = FALLING;
            end
        end

        DIGGING: begin
            if (!ground) begin
                // Reached other side while digging - fall
                next_state = FALLING;
                next_fall_counter = 1;
                // Resume walking in the direction stored before digging
                if (dig_dir == 0) begin
                    next_state = WALK_LEFT;
                end else begin
                    next_state = WALK_RIGHT;
                end
                next_fall_counter = 0;
            end else if (bump_left || bump_right) begin
                // Being bumped while digging has no effect
            end else begin
                next_state = DIGGING;
            end
        end

        SPLATTERED: begin
            next_state = SPLATTERED;
            next_fall_counter = 0;
        end
    endcase
end

endmodule

