module TopModule (
    input  clk,
    input  reset,
    input  [2:0] s,
    output fr2,
    output fr1,
    output fr0,
    output dfr
);

    wire [2:0] s_synced;
    reg  [2:0] s_prev;
    reg  [1:0] level_state; // 00: above s2, 01: between s2 and s1, 10: between s1 and s0, 11: below s0
    reg        dfr_reg;

    // Synchronize inputs
    always @(posedge clk) begin
        if (reset) begin
            s_prev       <= 3'b000;
            level_state  <= 2'b11; // below s0
            dfr_reg      <= 1'b1;
        end else begin
            s_prev       <= s;
            // Determine level state based on current sensors
            if (s[2]) level_state <= 2'b00; // above s2
            else if (s[1]) level_state <= 2'b01; // between s2 and s1
            else if (s[0]) level_state <= 2'b10; // between s1 and s0
            else       level_state <= 2'b11; // below s0

            // dfr logic: increase flow if previous level was lower than current
            // Previous lower means we transitioned from a higher state to a lower state index? 
            // Actually, "previous level was lower than the current level" means level_state now is higher (less empty) than before.
            // level_state encoding: 11 (lowest) -> 10 -> 01 -> 00 (highest)
            // If level_state increases (e.g., 10 -> 01), dfr should be 1.
            if ((s_prev[1] ^ s[1]) || (s_prev[2] ^ s[2])) begin
                 // Simple heuristic: if any higher sensor turned on, we went up.
                 // More precise: check if new state is "higher" than old state.
                 // State values: 00=4, 01=3, 10=2, 11=1 (inverted index)
                 // Let's just assert dfr if we are not at the top and sensors changed upwards.
                 dfr_reg <= 1'b1; 
            end else begin
                 dfr_reg <= 1'b0; 
            end
        end
    end

    // Output assignments based on level_state and dfr
    assign fr0 = (level_state != 2'b00); // fr0 is on except above s2? 
    // Table check:
    // Above s2: None -> fr0=0, fr1=0, fr2=0
    // Between s2 and s1: fr0
    // Between s1 and s0: fr0, fr1
    // Below s0: fr0, fr1, fr2

    assign fr1 = (level_state == 2'b10) | (dfr_reg & (level_state == 2'b11)); 
    // Between s1 and s0 (10) -> fr1 on. Below s0 (11) -> fr1 on if dfr? Spec says below s0 fr0,fr1,fr2 always. 
    // If dfr indicates level went up, but we are at bottom, we keep all on? 
    // Let's re-read: "If the sensor change indicates that the previous level was lower than the current level, the flow rate should be increased by opening the Supplemental flow valve (controlled by dfr)."
    // Below s0 is max flow. If we are below s0, we are already at max. Increasing it does nothing.
    // Between s1 and s0: nominal is fr0, fr1. If dfr, we might need fr2? No, table says between s1 and s0 is fr0, fr1.
    // Actually, dfr adds fr2? "increased by opening the Supplemental flow valve (controlled by dfr)".
    // Usually supplemental adds the next stage. fr2 is max.
    // Let's look at the table again.
    // Below s0: fr0, fr1, fr2.
    // Between s1 and s0: fr0, fr1.
    // Between s2 and s1: fr0.
    // Above s2: None.
    // So dfr likely asserts fr2 when applicable, or enables an extra valve.
    // The port is `dfr`. The output list is `fr2, fr1, fr0, dfr`.
    // So `dfr` is a distinct output, likely the control signal for the supplemental valve.
    // The table says "Nominal Flow Rate Inputs to be Asserted: fr0, fr1, fr2".
    // This implies fr0, fr1, fr2 are the flow rate outputs.
    // And `dfr` is the "Supplemental flow valve" control.
    // So the outputs are fr2, fr1, fr0 (the valves) and dfr (the supplemental control).
    // Wait, the port list is: output fr2, output fr1, output fr0, output dfr.
    // The table lists "Nominal Flow Rate Inputs to be Asserted: None, fr0, fr0, fr1, fr0, fr1, fr2".
    // This means fr0, fr1, fr2 are the outputs representing the flow rate.
    // And `dfr` is an additional output for the supplemental valve logic.
    // Let's assume `fr2`, `fr1`, `fr0` drive the valves.
    // And `dfr` is a separate output that gets set when the level rises.

    // Let's drive fr0, fr1, fr2 based on level_state.
    // Above s2 (00): 000
    // Between s2 and s1 (01): fr0 on -> 100 (fr2=0, fr1=0, fr0=1)
    // Between s1 and s0 (10): fr0, fr1 on -> 110 (fr2=0, fr1=1, fr0=1)
    // Below s0 (11): fr0, fr1, fr2 on -> 111 (fr2=1, fr1=1, fr0=1)

    // What about dfr?
    // dfr should be 1 if the level rose since last check.
    // The spec says: "If the sensor change indicates that the previous level was lower than the current level, the flow rate should be increased by opening the Supplemental flow valve (controlled by dfr)."
    // So dfr = 1 when a rise is detected.

    // Let's refine the logic.
    always @(posedge clk) begin
        if (reset) begin
            // Reset state: "equivalent to if the water level had been low for a long time"
            // no sensors asserted, and all four outputs asserted.
            // All four outputs: fr2, fr1, fr0, dfr.
            // So set all to 1.
            // Also set internal state to below s0.
            s_prev <= 3'b000;
            // Outputs will be driven by the assign statements or a separate always block.
            // Here we just set the registers if we had them, but we use wires/assign.
            // Let's use a register block for outputs to handle reset easily.
        end
    end

    // We need to handle the reset for the outputs.
    // Let's use regs for the outputs to make reset straightforward.
    reg fr2_reg, fr1_reg, fr0_reg, dfr_reg_out;

    always @(posedge clk) begin
        if (reset) begin
            fr2_reg <= 1'b1;
            fr1_reg <= 1'b1;
            fr0_reg <= 1'b1;
            dfr_reg_out <= 1'b1;
            s_prev <= 3'b000;
        end else begin
            // Determine current level
            if (s[2]) begin
                // Above s2
                // Nominal: None
                fr2_reg <= 1'b0;
                fr1_reg <= 1'b0;
                fr0_reg <= 1'b0;
                // dfr logic: was previous level lower? 
                // If s_prev was not all 0 (or specifically not above s2), then level rose.
                // If s_prev was 000 (below s0) or 001/010/011 etc, and now s[2] is 1, level rose.
                // "previous level was lower than the current level"
                // Current is highest. Previous lower means any state other than above s2 previously.
                // Let's check if any sensor was off previously that is on now, or just state transition.
                // Simplest: if we are at top, and we weren't before, dfr = 1? 
                // Spec: "If the sensor change indicates that the previous level was lower than the current level, the flow rate should be increased by opening the Supplemental flow valve (controlled by dfr)."
                // If we go above s2, we turn off all flow (None). Does dfr turn on? 
                // "increased by opening...". If we turn off main valves, opening supplemental might be the action.
                // But usually, above s2 means flow zero. 
                // Let's look at the reset condition: "resets the state machine to a state equivalent to if the water level had been low for a long time (no sensors asserted, and all four outputs asserted)."
                // This implies when reset happens, outputs are 1111.
                // When above s2, nominal is None. So fr2/fr1/fr0 should be 0.
                // What about dfr? If we reset to "low for long time", dfr is 1.
                // If we go above s2, we might want to keep dfr behavior consistent.
                // Let's assume dfr tracks if a rise occurred *to* the current state.
                // If we are above s2, we just rose there (or were there). 
                // Let's just set dfr based on transition detection.

                if (!(|s_prev)) begin
                     // Rose from below s0 to above s2.
                     dfr_reg_out <= 1'b1;
                end else begin
                     // Check if we rose from a lower state.
                     // If s_prev had fewer sensors on, or lower sensors on.
                     // Since current is max sensors (3), if prev had < 3, we rose.
                     if ($popcount(s_prev) < 3) begin
                        dfr_reg_out <= 1'b1;
                     end else begin
                        dfr_reg_out <= 1'b0; // Was already above
                     end
                end
            end else if (s[1]) begin
                // Between s2 and s1
                // Nominal: fr0
                fr2_reg <= 1'b0;
                fr1_reg <= 1'b0;
                fr0_reg <= 1'b1;
                // dfr logic
                if (!(|s_prev) || (s_prev[1] == 1'b0 && s[1] == 1'b1)) begin
                     // Rose from below or from above s2? 
                     // If s_prev was 000 or 001 (below s1) and now s[1] is on (and s[2] off), we rose.
                     // Actually, if s_prev was 000 (below s0), level rose.
                     // If s_prev was 010 (s[1] on, s[2] off)? That is the current state. 
                     // Let's simplify: if current state is "higher" than prev state.
                     // State order: 11 (below s0) -> 10 (s1-s0) -> 01 (s2-s1) -> 00 (above s2).
                     // Wait, my encoding earlier: 
                     // 00: above s2
                     // 01: between s2 and s1
                     // 10: between s1 and s0
                     // 11: below s0
                     // So "rising" means state index decreasing? 
                     // 11 -> 10 -> 01 -> 00. 
                     // This is confusing. Let's use the sensor bits.
                     // "previous level was lower than the current level"
                     // Lower level = fewer sensors asserted (generally), or sensors on are lower.
                     // If current s has a sensor on that prev didn't, and it's a higher sensor, we rose.
                     // If current s has a lower sensor on that prev didn't, we might have fallen/rise depending.
                     // Let's use the level_state logic defined later or just simple transition.

                     // Let's stick to: dfr is 1 if the current level state is "higher" (less empty) than the previous level state.
                     // I will define a simple state machine for level_state inside the always block.
                end
            end else if (s[0]) begin
                // Between s1 and s0
                // Nominal: fr0, fr1
                fr2_reg <= 1'b0;
                fr1_reg <= 1'b1;
                fr0_reg <= 1'b1;
                // dfr logic
            end else begin
                // Below s0
                // Nominal: fr0, fr1, fr2
                fr2_reg <= 1'b1;
                fr1_reg <= 1'b1;
                fr0_reg <= 1'b1;
                // dfr logic: if we rose to here from lower? Can't get lower than below s0.
                // But we can rise from below s0 to somewhere else. 
                // If we are below s0, dfr might be 0 unless we just rose from even lower (impossible) or this is the initial state after reset.
                // Reset sets dfr to 1. So after reset, if level is below s0, dfr stays 1?
                // Spec: "resets the state machine to a state equivalent to if the water level had been low for a long time (no sensors asserted, and all four outputs asserted)."
                // So after reset, all outputs 1. This matches "below s0" nominal + dfr=1.
            end
        end
    end

    // Assign outputs
    assign fr2 = fr2_reg;
    assign fr1 = fr1_reg;
    assign fr0 = fr0_reg;
    assign dfr = dfr_reg_out;

endmodule
